#include "HardwareBenchSelfTest.h"
namespace dnxr { HardwareBenchSelfTestResult HardwareBenchSelfTest::runDryRunSelfTest(RealNeuralChipHAL& hal, const HardwareBenchSessionManifest& manifest) const { HardwareBenchSelfTestResult r; r.deviceReachable=hal.init(manifest.hardwareSerial.empty()?"hardware_bench":manifest.hardwareSerial); if(!r.deviceReachable) return r; r.firmwareVersionReadable=!hal.deviceIdentity().firmwareHash.empty(); const auto caps=hal.getCapabilities(); r.capabilitiesReadable=caps.supportsClosedLoopFeedback || caps.supportsHardwareCutoff; r.ackChannelAlive=hal.handshake() && hal.readAck().packetAccepted; r.telemetryChannelAlive=hal.readTelemetry()!="telemetry_disconnected"; hal.emergencyStop("dry_run_cutoff_test"); r.emergencyStopAccepted=hal.status().emergencyLatched; r.outputDisabledByDefault=!manifest.activeStimulationEnabled || manifest.maxOutputCeiling<=0.0f; return r; } }
